671	// without any opening bracket or quote. "U.S.A." style initialisms are not
672	// listed: they usually do end a sentence when they come last, and guessing
673	// otherwise would trade one error for another.
674	const ABBREVIATIONS = new Set(['mr', 'mrs', 'ms', 'dr', 'prof', 'st', 'sr', 'jr', 'vs', 'e.g', 'i.e']);
675	
676	// A terminator run ("." "?!" "...") plus any closing quotes or brackets, and
677	// only where whitespace or the end of the text follows. Requiring that keeps
678	// decimals ("3.14"), domains ("example.com") and "a.b.c" in one piece.
679	const TERMINATOR_PATTERN = /([.!?]+)(["'”’)\]]*)(?=\s|$)/g;
680	
681	function endsWithAbbreviation(before) {
682	  const last = before.match(/(\S+)$/);
683	  if (last === null) {
684	    return false;
685	  }
686	  const word = last[1].replace(/^["'“‘(\[]+/, '').toLowerCase();
687	  return ABBREVIATIONS.has(word);
688	}
