692	 *
693	 * A sentence is a stretch of text containing at least one word and ending at a
694	 * terminator run, or at the end of the text. A lone period after a known
695	 * abbreviation does not end a sentence.
696	 *
697	 * @param {string} text
698	 * @returns {number}
699	 */
700	function sentenceCount(text) {
701	  assertText('sentenceCount', text);
702	  let count = 0;
703	  let start = 0;
704	  for (const match of text.matchAll(TERMINATOR_PATTERN)) {
705	    const before = text.slice(start, match.index);
706	    if (match[1] === '.' && endsWithAbbreviation(before)) {
