708	    }
709	    if (tokenize(before).length > 0) {
710	      count += 1;
711	    }
712	    start = match.index + match[0].length;
713	  }
714	  if (tokenize(text.slice(start)).length > 0) {
715	    count += 1;
716	  }
717	  return count;
